begin;
create table if not exists public.security_audit_events(id uuid primary key default gen_random_uuid(),actor_id uuid references auth.users(id) on delete set null,event_type text not null,resource_type text,resource_id uuid,outcome text not null default 'success',risk_score integer not null default 0 check(risk_score between 0 and 100),metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index if not exists security_audit_events_actor_created_idx on public.security_audit_events(actor_id,created_at desc);
create index if not exists security_audit_events_type_created_idx on public.security_audit_events(event_type,created_at desc);
alter table public.security_audit_events enable row level security;
drop policy if exists security_audit_events_no_client_read on public.security_audit_events;
create policy security_audit_events_no_client_read on public.security_audit_events for select to authenticated using(false);
create or replace function public.record_security_event(p_event_type text,p_resource_type text default null,p_resource_id uuid default null,p_outcome text default 'success',p_risk_score integer default 0,p_metadata jsonb default '{}'::jsonb) returns void language plpgsql security invoker set search_path=public,extensions,pg_temp as $$ begin insert into public.security_audit_events(actor_id,event_type,resource_type,resource_id,outcome,risk_score,metadata) values(auth.uid(),left(p_event_type,100),left(p_resource_type,100),p_resource_id,left(coalesce(p_outcome,'success'),50),greatest(0,least(coalesce(p_risk_score,0),100)),coalesce(p_metadata,'{}'::jsonb)); end; $$;
revoke all on function public.record_security_event(text,text,uuid,text,integer,jsonb) from public,anon; grant execute on function public.record_security_event(text,text,uuid,text,integer,jsonb) to authenticated;
create or replace function public.school_search_rate_guard(p_fingerprint text default null) returns boolean language plpgsql security definer set search_path=public,extensions,pg_temp as $$ declare uid uuid:=auth.uid(); n integer; begin if uid is null then return false; end if; select count(*) into n from public.security_audit_events where actor_id=uid and event_type='school.search' and created_at>now()-interval '1 minute'; if n>=60 then insert into public.security_audit_events(actor_id,event_type,outcome,risk_score,metadata) values(uid,'rate_limit.triggered','blocked',70,jsonb_build_object('resource','school.search','window','1m','count',n)); return false; end if; return true; end; $$;
revoke all on function public.school_search_rate_guard(text) from public,anon; grant execute on function public.school_search_rate_guard(text) to authenticated;
commit;
